	private class OneShotAnalyzerAction : ListingContextAction {
		private Analyzer analyzer;
		private Program canAnalyzeProgram;
		private bool canAnalyze;

		public OneShotAnalyzerAction(Analyzer analyzer) : base(analyzer.getName(), this.getName())
    {
			this.analyzer = analyzer;
			setMenuBarData(new MenuData(new string[] { "Analysis", "One Shot", analyzer.getName() },
				null, ANALYZE_GROUP_NAME));
			setHelpLocation(new HelpLocation("AutoAnalysisPlugin", "Auto_Analyzers"));

			setContextClass(typeof(ListingActionContext), true);
		}

		/* @Override */
		public void actionPerformed(ListingActionContext context) {
			AddressSetView set;
			if (context.hasSelection()) {
				set = context.getSelection();
			}
			else {
				Memory memory = context.getProgram().getMemory();
				AddressSet external = new AddressSet(AddressSpace.EXTERNAL_SPACE.getMinAddress(),
					AddressSpace.EXTERNAL_SPACE.getMaxAddress());
				set = memory.union(external);
			}

			AutoAnalysisManager analysisMgr =
				AutoAnalysisManager.getAnalysisManager(context.getProgram());

			Program program = context.getProgram();
			Options options = program.getOptions(Program.ANALYSIS_PROPERTIES);
			options = options.getOptions(analyzer.getName());
			analyzer.optionsChanged(options, program);

			OneShotAnalysisCommand cmd =
				new OneShotAnalysisCommand(analyzer, set, analysisMgr.getMessageLog());
			analysisMgr.addListener(cmd);
			analysisMgr.schedule(cmd, analyzer.getPriority().priority());

			tool.setStatusInfo("Analysis scheduled: " + analyzer.getName());
		}

		/* @Override */
		public bool isEnabledForContext(ListingActionContext context) {
			Program p = context.getProgram();
			if (p != canAnalyzeProgram) {
				canAnalyzeProgram = p;
				canAnalyze = analyzer.canAnalyze(p);
			}
			return canAnalyze;
		}
	}

	private class FirstTimeAnalyzedCallback : AutoAnalysisManagerListener {
		/* @Override */
		public void analysisEnded(AutoAnalysisManager manager, bool isCancelled) {
			manager.removeListener(this);

			if (!isCancelled) {
				tool.firePluginEvent(new FirstTimeAnalyzedPluginEvent(
					this.getName(), manager.getProgram()));
			}
		}
	}

	// Small class to register actions by name before the various editors have been shown. We need
	// this for the Analysis OptionsDialog actions to appear in the key binding options.
	private class AnalysisOptionsSharedActionPlaceholder : SharedDockingActionPlaceholder {

		private string actionName;

		AnalysisOptionsSharedActionPlaceholder(string actionName) {
			this.actionName = actionName;
		}

		/* @Override */
		public string getOwner() {
			return OPTIONS_OWNER;
		}

		/* @Override */
		public string getName() {
			return actionName;
		}
	}

}
